@Entry
@Component
struct SwiperNextPrevMarginExample67 {
  private swiperController: SwiperController = new SwiperController()
  private data: MyDataSource67 = new MyDataSource67([])

  aboutToAppear(): void {
    let list: number[] = []
    for (let i = 1; i <= 10; i++) {
      list.push(i);
    }
    this.data = new MyDataSource67(list)
  }

  build() {
    Column({ space: 5 }) {
      Swiper(this.swiperController) {
        LazyForEach(this.data, (item: string,index:number) => {
          SwiperItemComponent67({
            item: item,
          }).reuseId(index + "")
        }, (item: string) => item)
      }
      .cachedCount(2)
      .index(1)
      .autoPlay(false)
      .interval(4000)
      .nextMargin(15)
      .vertical(false)
      .prevMargin(6)
      .displayCount(1)
      .borderWidth(0)
      .width(250)
       .displayMode(SwiperDisplayMode.STRETCH)
      .loop(false)
      .duration(1000)
      .itemSpace(10)
      .key("swiperNextPrevMargin67")

      Row({ space: 12 }) {
        Button('showNext')
          .onClick(() => {
            this.swiperController.showNext()
          })
        Button('showPrevious')
          .onClick(() => {
            this.swiperController.showPrevious()
          })
      }.margin(5)
    }.width('100%')
    .margin({ top: 5 }).key('ColumnSwiper67')
  }
}

